<script setup lang="ts">
import {computed,onMounted,reactive,ref} from "vue";import {Pige360SessionClient,type ApiProblem} from "@pige360/auth";
type Row=Record<string,any>;const api=new Pige360SessionClient();const ready=ref(false),auth=ref(false),busy=ref(false),error=ref(""),notice=ref("");const privacyNotice=ref<Row|null>(null);const email=ref(""),password=ref("");const ctx=ref<Row>({branding:{},enrollments:[],attendance:{},library_loans:[],transport:[],notices:[],requests:[],health:{people:[],records:[],incidents:[],medications:[]},transport_events:[],consent_purposes:[],consents:[],privacy_requests:[]});const req=reactive({request_type:"academic",subject:"",description:"",priority:"normal",department:"Secretaria",sla_hours:72});const privacy=reactive({request_type:"access",description:""});const b=computed(()=>ctx.value.branding||{}),school=computed(()=>b.value.short_name||b.value.trade_name||b.value.legal_name||"Instituição");function m(e:unknown){const p=(e as Error&{problem?:ApiProblem}).problem;return p?.detail||(e instanceof Error?e.message:"Erro");}function theme(){document.documentElement.style.setProperty("--brand-primary",b.value.primary_color||"#006D77");document.documentElement.style.setProperty("--brand-secondary",b.value.secondary_color||"#0D1B2A");document.title=`${school.value} — Aluno`;}async function load(){const portal=await api.request<Row>("/portal/student/me");const sid=portal.student?.id;const pid=portal.person?.id;const [health,events,reportCard,integralization,purposes,consents,privacyRequests]=await Promise.all([api.request<Row>("/health/me").catch(()=>({people:[],records:[],incidents:[],medications:[]})),sid?api.request<Row>(`/transport/students/${sid}/events`).catch(()=>({items:[]})):Promise.resolve({items:[]}),sid?api.request<Row>(`/pedagogy/students/${sid}/report-card`).catch(()=>({enrollments:[]})):Promise.resolve({enrollments:[]}),sid?api.request<Row>(`/academic/students/${sid}/integralization`).catch(()=>({enrollments:[]})):Promise.resolve({enrollments:[]}),api.request<Row>("/compliance/consent-purposes").catch(()=>({items:[]})),pid?api.request<Row>(`/compliance/persons/${pid}/consents`).catch(()=>({items:[]})):Promise.resolve({items:[]}),api.request<Row>("/compliance/data-subject-requests").catch(()=>({items:[]}))]);ctx.value={...portal,health,transport_events:events.items||[],report_card:reportCard,integralization,consent_purposes:purposes.items||[],consents:consents.items||[],privacy_requests:privacyRequests.items||[]};theme();}async function boot(){try{await api.initialize();auth.value=!!api.tokens;if(auth.value)await load();}catch(e){error.value=m(e);}finally{ready.value=true;}}async function login(){busy.value=true;try{await api.login(email.value,password.value);auth.value=true;await load();}catch(e){error.value=m(e);}finally{busy.value=false;}}async function logout(){await api.logout();auth.value=false;}async function renewLoan(id:string){busy.value=true;try{await api.request(`/library/loans/${id}/renew`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({reason:"Renovação solicitada pelo aluno"})});await load();notice.value="Empréstimo renovado.";}catch(e){error.value=m(e);}finally{busy.value=false;}}
function activeConsent(code:string){return ctx.value.consents?.find((x:any)=>x.purpose_code===code&&x.state==="granted")||null;}function adult(){const b=ctx.value.person?.birth_date;if(!b)return false;const born=new Date(`${b}T00:00:00`),now=new Date();let age=now.getFullYear()-born.getFullYear();if(now.getMonth()<born.getMonth()||(now.getMonth()===born.getMonth()&&now.getDate()<born.getDate()))age--;return age>=18;}async function readPrivacyNotice(p:Row){if(!p.privacy_notice_id)return;busy.value=true;try{privacyNotice.value=await api.request<Row>(`/compliance/privacy-notices/${p.privacy_notice_id}`);}catch(e){error.value=m(e);}finally{busy.value=false;}}async function grantConsent(p:Row){if(!ctx.value.person?.id||!p.privacy_notice_id)return;busy.value=true;try{await api.request("/compliance/consents",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({subject_person_id:ctx.value.person.id,granted_by_person_id:ctx.value.person.id,purpose_code:p.code,privacy_notice_id:p.privacy_notice_id,channel:"mobile",evidence:{surface:"student-app",affirmative_action:true}})});notice.value="Consentimento registrado.";await load();}catch(e){error.value=m(e);}finally{busy.value=false;}}async function revokeConsent(c:Row){busy.value=true;try{await api.request(`/compliance/consents/${c.id}/revoke`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({reason:"Revogação solicitada pelo titular no Portal do Aluno"})});notice.value="Consentimento revogado.";await load();}catch(e){error.value=m(e);}finally{busy.value=false;}}async function privacyRequest(){if(!ctx.value.person?.id)return;busy.value=true;try{await api.request("/compliance/data-subject-requests",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({subject_person_id:ctx.value.person.id,request_type:privacy.request_type,description:privacy.description||null,priority:"normal"})});notice.value="Solicitação LGPD registrada.";privacy.description="";await load();}catch(e){error.value=m(e);}finally{busy.value=false;}}
async function send(){busy.value=true;try{await api.request("/service-requests",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(req)});notice.value="Solicitação enviada.";Object.assign(req,{request_type:"academic",subject:"",description:"",priority:"normal",department:"Secretaria",sla_hours:72});await load();}catch(e){error.value=m(e);}finally{busy.value=false;}}function date(v:any){return v?new Intl.DateTimeFormat("pt-BR",{dateStyle:"short"}).format(new Date(v)):"—";}onMounted(boot);
</script>
<template><div v-if="!ready" class="center">Carregando…</div><div v-else-if="!auth" class="login"><form @submit.prevent="login"><div class="mark">▣</div><span>Portal do Aluno</span><h1>Minha vida acadêmica</h1><label>E-mail<input v-model="email" type="email" required></label><label>Senha<input v-model="password" type="password" required></label><p v-if="error" class="error">{{error}}</p><button>Entrar</button></form></div><div v-else class="shell"><header><div><strong>{{school}}</strong><small>Portal do Aluno</small></div><button @click="logout">Sair</button></header><main><div v-if="error" class="flash error">{{error}}</div><div v-if="notice" class="flash success">{{notice}}</div><section class="hero"><span>Bem-vindo(a)</span><h1>{{ctx.person?.social_name||ctx.person?.full_name}}</h1><p>{{ctx.enrollments?.[0]?.program_name||'Vida acadêmica'}} · {{ctx.enrollments?.[0]?.class_group_name||'Sem turma ativa'}}</p></section><section class="metrics"><article><span>Frequência</span><strong>{{ctx.attendance?.percentage||'0.00'}}%</strong><small>{{ctx.attendance?.counted_sessions||0}} sessões</small></article><article><span>Matrícula</span><strong>{{ctx.student?.registration_number}}</strong><small>{{ctx.enrollments?.[0]?.academic_year_name||'—'}}</small></article><article><span>Biblioteca</span><strong>{{ctx.library_loans?.filter((x:any)=>x.state==='open').length||0}}</strong><small>empréstimos ativos</small></article></section><section class="panel"><h2>Boletim e resultados</h2><div v-for="en in ctx.report_card?.enrollments||[]" :key="en.enrollment.id" class="rows"><div v-for="r in en.results" :key="r.id"><div><strong>{{r.component_name}}</strong><small>{{r.period_name}} · {{r.outcome}}</small></div><span class="pill">{{Number(r.final_score).toFixed(2)}} · {{Number(r.attendance_percentage).toFixed(2)}}%</span></div><p v-if="!en.results?.length" class="empty">Ainda não há resultados consolidados.</p></div><p v-if="!ctx.report_card?.enrollments?.length" class="empty">Boletim ainda não disponível.</p></section><section v-if="ctx.integralization?.enrollments?.some((x:any)=>Number(x.curriculum?.components_total||0)>0)" class="panel"><h2>Integralização curricular</h2><div v-for="en in ctx.integralization.enrollments" :key="en.enrollment.id" class="rows"><div><div><strong>{{en.enrollment.program_name}} · {{en.enrollment.curriculum_name}}</strong><small>{{en.curriculum.components_completed}}/{{en.curriculum.components_total}} componentes · {{en.curriculum.workload_hours_completed}}/{{en.curriculum.workload_hours_total}}h</small></div><span class="pill">{{en.curriculum.completion_percentage}}%</span></div><div v-for="i in en.internships" :key="i.id"><div><strong>Estágio curricular</strong><small>{{i.completed_hours}}/{{i.required_hours}}h</small></div><span class="pill">{{i.state}}</span></div><div v-for="a in en.complementary_activities" :key="a.id"><div><strong>{{a.title}}</strong><small>{{a.category}} · {{a.approved_hours}}h homologadas</small></div><span class="pill">{{a.state}}</span></div><div v-for="t in en.theses" :key="t.id"><div><strong>{{t.title}}</strong><small>Trabalho de conclusão</small></div><span class="pill">{{t.state}}<template v-if="t.grade"> · {{t.grade}}</template></span></div><div v-if="en.pending_prerequisites?.length"><div><strong>Pré-requisitos pendentes</strong><small>{{en.pending_prerequisites.map((x:any)=>x.prerequisite_name).join(', ')}}</small></div><span class="pill">{{en.pending_prerequisites.length}}</span></div></div></section><section class="grid"><div class="panel"><h2>Frequência recente</h2><div class="rows"><div v-for="r in ctx.attendance?.recent" :key="r.class_session_id+r.scheduled_start"><div><strong>{{r.component_name||'Componente'}}</strong><small>{{date(r.scheduled_start)}}</small></div><span class="pill">{{r.status_code}}</span></div><p v-if="!ctx.attendance?.recent?.length" class="empty">Sem registros de frequência.</p></div></div><div class="panel"><h2>Avisos</h2><article class="notice" v-for="n in ctx.notices?.slice(0,8)" :key="n.id"><strong>{{n.title}}</strong><p>{{n.body}}</p><small>{{date(n.created_at)}}</small></article><p v-if="!ctx.notices?.length" class="empty">Sem avisos.</p></div></section><section class="grid"><div class="panel"><h2>Eventos de transporte</h2><div class="rows"><div v-for="t in ctx.transport_events?.slice(0,10)" :key="t.id"><div><strong>{{t.event_type==='boarded'?'Embarque':t.event_type==='disembarked'?'Desembarque':t.event_type}}</strong><small>{{t.route_name}} · {{t.stop_name||'—'}}</small></div><span>{{date(t.occurred_at)}}</span></div><p v-if="!ctx.transport_events?.length" class="empty">Sem eventos recentes.</p></div></div><div class="panel"><h2>Saúde autorizada</h2><article class="notice" v-for="i in ctx.health?.incidents?.slice(0,6)" :key="i.id"><strong>{{i.incident_type}}</strong><p>{{i.summary}}</p><small>{{date(i.occurred_at)}} · {{i.state}}</small></article><article class="notice" v-for="med in ctx.health?.medications?.slice(0,6)" :key="med.id"><strong>{{med.medication_name}} · {{med.dosage}}</strong><p>{{med.instructions}}</p><small>{{date(med.starts_on)}} a {{date(med.ends_on)}}</small></article><p v-if="!ctx.health?.incidents?.length&&!ctx.health?.medications?.length" class="empty">Sem informações de saúde visíveis.</p></div></section>
<section class="grid"><div class="panel"><h2>Privacidade e consentimentos</h2><article class="notice" v-for="p in ctx.consent_purposes" :key="p.code"><strong>{{p.name}}</strong><p>{{p.purpose}}</p><small>{{p.privacy_notice_title||'Aviso de privacidade'}}<template v-if="p.privacy_notice_version"> · v{{p.privacy_notice_version}}</template></small><div class="right"><button v-if="p.privacy_notice_id" class="small" @click="readPrivacyNotice(p)">Ler aviso</button><button v-if="adult()&&!activeConsent(p.code)" class="small" :disabled="!p.privacy_notice_id" @click="grantConsent(p)">Autorizar</button><button v-if="activeConsent(p.code)" class="small" @click="revokeConsent(activeConsent(p.code))">Revogar</button><small v-if="!adult()&&!activeConsent(p.code)">Consentimento deve ser realizado pelo responsável legal.</small></div></article><p v-if="!ctx.consent_purposes?.length" class="empty">Nenhuma finalidade consentível publicada.</p></div><form class="panel form" @submit.prevent="privacyRequest"><h2>Direitos do titular</h2><label>Tipo<select v-model="privacy.request_type"><option value="access">Acesso</option><option value="export">Exportação</option><option value="rectification">Retificação</option><option value="restriction">Restrição</option><option value="objection">Oposição</option><option value="anonymization">Anonimização</option></select></label><label>Descrição<textarea v-model="privacy.description" rows="4"></textarea></label><button>Registrar solicitação LGPD</button><small v-for="r in ctx.privacy_requests?.slice(0,5)" :key="r.id">{{r.protocol}} · {{r.request_type}} · {{r.state}}</small></form></section>
<section v-if="privacyNotice" class="panel"><div class="right"><button class="small" @click="privacyNotice=null">Fechar aviso</button></div><h2>{{privacyNotice.title}}</h2><small>{{privacyNotice.code}} · v{{privacyNotice.version}} · SHA-256 {{privacyNotice.sha256}}</small><p style="white-space:pre-wrap">{{privacyNotice.content}}</p></section><section class="grid"><div class="panel"><h2>Biblioteca</h2><div class="rows"><div v-for="l in ctx.library_loans" :key="l.id"><div><strong>{{l.title}}</strong><small>Devolução {{date(l.due_at)}}</small></div><div class="right"><span>{{l.state}}</span><button v-if="l.state==='open'" class="small" @click="renewLoan(l.id)">Renovar</button></div></div><p v-if="!ctx.library_loans?.length" class="empty">Nenhum empréstimo.</p></div><h2 class="space">Transporte</h2><div class="rows"><div v-for="t in ctx.transport" :key="t.id"><div><strong>{{t.route_name}}</strong><small>{{t.vehicle||'Veículo não informado'}}</small></div><span>{{t.state}}</span></div></div></div><form class="panel form" @submit.prevent="send"><h2>Solicitar atendimento</h2><label>Assunto<input v-model="req.subject" required></label><label>Tipo<input v-model="req.request_type" required></label><label>Descrição<textarea v-model="req.description" rows="5"></textarea></label><button>Enviar solicitação</button><small v-for="r in ctx.requests?.slice(0,5)" :key="r.id">{{r.protocol}} · {{r.subject}} · {{r.state}}</small></form></section></main></div></template>
